source.bookSourceComment:
by狼崽儿 //2026.7.1
有些资源只有一条线路，所以单线路时换线路没有用。
修改了目录列表，确保能正确换线路。//2026.7.6

2026.8.1
如果网站失效，就去该漫蛙的发布页https://ManWaLa.CC/进去任一漫画网站再跳到动漫网页，获取最新网站更新源域名即可。
套了第三方播放器，不依赖阅读自身的解析能力，提高了播放链接的播放成功率。以下是只给出M3U8直链文本而不拉起播放器的正文规则，直接复制粘贴即可。
@js:
var iframe = src.match(/<iframe[^>]*src="([^"]+)"/);
var videoUrl = '';
if (iframe) {
  var m = iframe[1].match(/[?&]url=([^&]+)/);
  if (m) {
    videoUrl = decodeURIComponent(m[1]);
  }
}
result = videoUrl;

如果想优先播放直链，就把原正文规则的java.startBrowser(playUrl, book.name + ' - ' + chapter.title);改成java.startBrowser(videoUrl || playerUrl, book.name + ' - ' + chapter.title);

source.exploreUrl:
@js:
var result = [];
var push = (title, typeId, tag, size) => result.push({
    title: title,
    url: "/api/cate/," + JSON.stringify({
        "body": "{\"page\":{\"page\":{{page}},\"pageSize\":36},\"category\":\"video\",\"sort\":0,\"comic\":{\"status\":-1,\"day\":0,\"year\":0,\"tag\":\"\"},\"video\":{\"typeId\":" + typeId + ",\"tag\":\"" + tag + "\",\"area\":\"\",\"lang\":\"\",\"status\":-1,\"year\":0},\"novel\":{\"status\":-1,\"day\":0,\"sortId\":0}}",
        "method": "POST"
    }),
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: size
    }
});

// typeId名称映射
var types = ["", "国产", "日韩", "欧美", "港台", "电影", "里番"];
// 全部tag列表（含空=全部）
var tags = ["全部", "动画", "喜剧", "奇幻", "剧情", "冒险", "动作", "科幻", "爱情", "儿童", "短片", "家庭", "悬疑", "运动"];

for (var t = 1; t <= 6; t++) {
    for (var g = 0; g < tags.length; g++) {
        var title = types[t] + '-' + tags[g];
        var tag = (g === 0) ? '' : tags[g];
        var size = (g === 0) ? 1 : 0.25;
        push(title, t, tag, size);
    }
}

JSON.stringify(result);

ruleContent.content:
@js:
var iframe = src.match(/<iframe[^>]*src="([^"]+)"/);
var playerUrl = '';
var videoUrl = '';
if (iframe) {
  playerUrl = iframe[1];
  var m = iframe[1].match(/[?&]url=([^&]+)/);
  if (m) { videoUrl = decodeURIComponent(m[1]); }
}
// 优先播放器地址，没有再播直链
var playUrl = playerUrl || videoUrl;
if (playUrl) {
  java.startBrowser(playUrl, book.name + ' - ' + chapter.title);
  java.toast('正在播放');
}
result = '【刷新正文】播放器:' + String.fromCharCode(10) + playerUrl + String.fromCharCode(10, 10) + '直链:' + String.fromCharCode(10) + videoUrl;

ruleToc.chapterList:
@js:
var m = String(book.intro).match(/来源◖(\d+)◗/);
var xu = (m && m[1]) ? m[1] : '0';
var gridId = (xu === '1') ? 'grid-1' : 'grid-0';
var start = src.indexOf('<div id="' + gridId + '"');
var end = src.indexOf('<div id="grid-', start + 10);
if (end < 0) { end = src.indexOf('<script', start + 10); }
if (end < 0) { end = src.length; }
var block = src.substring(start, end);
var list = [];
var re = new RegExp('<a href="(/video/\\d+/\\d+)"[^>]*class="episode-item"[^>]*>\\s*([^<]+)\\s*</a>', 'g');
var m;
while ((m = re.exec(block)) !== null) {
  list.push({ text: m[2].trim(), href: m[1] });
}
list

